<?php foreach(['in_progress'=>'Résultats à saisir','results_submitted'=>'Fabrications à valider'] as $state=>$title):$index=$state==='in_progress'?0:1;$pending=array_filter($orders,static function($order)use($state){return $order['status']===$state;});?>
<section id="butchery-production-kpi-<?=$index?>" class="entity-modal workspace-entity-modal feed-editor livestock-editor conversion-editor butchery-editor butchery-kpi-modal" role="dialog" aria-modal="true" aria-hidden="true" aria-labelledby="production-kpi-title-<?=$index?>">
<header><h2 id="production-kpi-title-<?=$index?>"><?=e($title)?></h2><button type="button" class="modal-close" data-workspace-modal-close aria-label="Fermer">×</button></header><div class="feed-form-body">
<?php if(!$pending):?><p class="butchery-empty">Aucune fabrication à cette étape.</p><?php else:?><table class="enterprise-table"><thead><tr><th>Date</th><th>Ordre / fiche</th><th>Prévu</th><th>Actions</th></tr></thead><tbody><?php foreach($pending as $order):?><tr><td><?=e(date('d/m/Y',strtotime($order['production_date'])))?></td><td><?=e($order['order_number'])?><small><?=e($order['recipe_name'])?></small></td><td><?=e($order['planned_input_kg'])?> kg</td><td><div class="butchery-production-actions"><?=$productionActions[$order['id']]??''?><button type="button" class="btn-secondary" data-workspace-modal-open="production-detail-<?=e($order['id'])?>">Consulter</button></div></td></tr><?php endforeach;?></tbody></table><?php endif;?>
</div><footer><button type="button" class="btn-secondary" data-workspace-modal-close>Fermer</button></footer></section><?php endforeach;?>
